<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/database.php';
$user=require_role(['committee']);$action=$_GET['action']??'list';
try{$pdo=db();if($action==='list'){$s=$pdo->query('SELECT id,message,sent_at,status FROM line_announcements ORDER BY id DESC LIMIT 50');json_response(['status'=>'success','data'=>$s->fetchAll()]);}
if($action==='send'){$d=json_input();$message=trim((string)($d['message']??''));if($message==='')json_response(['status'=>'error','message'=>'กรุณากรอกข้อความ'],422);$token=trim((string)($d['line_token']??''));$pdo->prepare('INSERT INTO line_announcements (message,sent_by,status) VALUES (?,?,?)')->execute([$message,$user['id'],$token?'sent':'draft']);if(!$token)json_response(['status'=>'success','message'=>'บันทึกประกาศแล้ว (ยังไม่ได้ส่ง เนื่องจากไม่ได้ระบุ Token)']);$ch=curl_init('https://notify-api.line.me/api/notify');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query(['message'=>$message]),CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$token,'Content-Type: application/x-www-form-urlencoded'],CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>15]);$body=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$ok=$code>=200&&$code<300;$pdo->prepare('UPDATE line_announcements SET status=? WHERE id=?')->execute([$ok?'sent':'failed',$pdo->lastInsertId()]);if(!$ok)json_response(['status'=>'error','message'=>'ส่ง LINE ไม่สำเร็จ กรุณาตรวจสอบ Token'],502);json_response(['status'=>'success','message'=>'ส่งประกาศ LINE เรียบร้อยแล้ว']);}
json_response(['status'=>'error','message'=>'ไม่พบคำสั่ง'],400);}catch(Throwable $e){error_log($e->getMessage());json_response(['status'=>'error','message'=>'เกิดข้อผิดพลาดของระบบ'],500);}
